output_schema:
Comprehensive API analysis for documentation generation
{
  "api_overview": {
    "title": "string",
    "version": "string",
    "base_url": "string",
    "description": "string",
    "api_type": "REST | GraphQL | gRPC | WebSocket"
  },
  "authentication": {
    "methods": [
      {
        "type": "api_key | oauth2 | bearer | basic | none",
        "location": "header | query | cookie",
        "parameter_name": "string",
        "description": "string",
        "example": "string"
      }
    ],
    "flows": ["string - OAuth flows if applicable"],
    "scopes": ["string - Available permission scopes"]
  },
  "endpoints": [
    {
      "id": "string - e.g., EP-001",
