      "path": "string",
      "summary": "string - One line description",
      "description": "string - Detailed description",
      "complexity": "simple | moderate | complex",
      "tags": ["string"],
      "parameters": {
        "path": [
          {
            "name": "string",
            "type": "string",
            "required": "boolean",
            "description": "string",
            "example": "string"
          }
        ],
        "query": ["same structure"],
        "header": ["same structure"]
      },
      "request_body": {
        "content_type": "string",
        "schema": "object - JSON Schema",
        "required_fields": ["string"],
        "example": "object"
      },
      "responses": [
        {
          "status_code": "number",
          "description": "string",
          "schema": "object",
          "example": "object"
        }
      ],
      "rate_limit": "string | null",
      "deprecated": "boolean"
    }
  ],
  "data_models": [
    {
      "name": "string",
      "description": "string",
      "properties": [
        {
          "name": "string",
          "type": "string",
          "required": "boolean",
          "description": "string",
          "constraints": "string | null"
        }
      ],
      "used_by_endpoints": ["string - Endpoint IDs"]
    }
  ],
  "error_codes": [
    {
      "code": "number",
      "name": "string",
      "description": "string",
      "common_causes": ["string"],
      "resolution": "string"
    }
  ],
  "documentation_plan": {
    "priority_endpoints": ["string - Endpoint IDs to document first"],
    "complexity_assessment": {
      "simple": "number - count",
      "moderate": "number",
      "complex": "number"
    },
    "estimated_pages": "number"
  }
